    eps = 1e-12
    norm = ops.sqrt(ops.add(ops.sum(ops.mul(adv, adv)), eps))
    adv_norm = ops.div(adv, norm)
    loss_raw = ops.neg(ops.logsigmoid(adv_norm))
    if weight is not None:
